export type Actor = 'user' | 'agent';

export type LayerType = 'raster' | 'vector' | 'ai-generated';

/**
 * A layer stores exactly one kind of content:
 * - `fabric`: a serialized Fabric.js object produced by the brush tool.
 * - `svg`: markup generated by the AI agent.
 *
 * The daemon persists this value as JSON in `layers.content`.
 */
export type LayerContent =
  | { kind: 'fabric'; json: string }
  | { kind: 'svg'; svg: string };

export interface LayerMetadata {
  createdBy: Actor;
  createdAt: number;
  prompt?: string;
}

export interface Layer {
  id: string;
  canvasId: string;
  name: string;
  type: LayerType;
  zIndex: number;
  visible: boolean;
  opacity: number;
  content: LayerContent;
  metadata: LayerMetadata;
  createdAt: number;
}

export interface Canvas {
  id: string;
  name: string;
  width: number;
  height: number;
  backgroundColor: string;
  revision: number;
  createdAt: number;
  updatedAt: number;
}

export interface CanvasHistoryState {
  canUndo: boolean;
  canRedo: boolean;
}

/** List ordering for `GET /paint/canvas`; defaults to `updated`. */
export type CanvasListSort = 'updated' | 'created';

/**
 * One row of the canvas library list: the document's identity plus the cheap
 * aggregates the gallery card needs (layer count, thumbnail marker). It never
 * carries thumbnail bytes — only whether a thumbnail exists and at which
 * revision the browser last uploaded it.
 */
export interface CanvasSummary {
  id: string;
  name: string;
  width: number;
  height: number;
  backgroundColor: string;
  layerCount: number;
  revision: number;
  hasThumbnail: boolean;
  thumbnailRevision: number | null;
  createdAt: number;
  updatedAt: number;
}

/** One page of the canvas library. `total` is the count before pagination. */
export interface CanvasListPage {
  items: CanvasSummary[];
  total: number;
  limit: number;
  offset: number;
}

export interface CanvasState extends Canvas {
  layers: Layer[];
}

export interface CanvasDocument extends CanvasState {
  history: CanvasHistoryState;
}

export interface CreateLayerInput {
  name: string;
  type: LayerType;
  content: LayerContent;
  visible?: boolean;
  opacity?: number;
  metadata?: Partial<LayerMetadata>;
}

export interface UpdateLayerPatch {
  name?: string;
  visible?: boolean;
  opacity?: number;
  content?: LayerContent;
}

export type PaintAction =
  | { type: 'canvas_create_layer'; layer: CreateLayerInput }
  | { type: 'canvas_update_layer'; layerId: string; patch: UpdateLayerPatch }
  | { type: 'canvas_delete_layer'; layerId: string };

export interface ApplyActionRequest {
  actor: Actor;
  action: PaintAction;
  expectedRevision?: number;
}

export interface HistoryRequest {
  expectedRevision?: number;
}

export interface SnapshotChangedEvent {
  type: 'snapshot_changed';
  canvasId: string;
  revision: number;
}

export interface CreateCanvasRequest {
  name?: string;
  width?: number;
  height?: number;
  backgroundColor?: string;
}

/**
 * `name` is the only mutable canvas field: identity, not geometry. The length
 * bound lives here so the daemon validator and the browser input cannot drift.
 */
export const MAX_CANVAS_NAME_LENGTH = 80;

export interface UpdateCanvasRequest {
  name: string;
}

export interface AiChatRequest {
  canvasId?: string;
  message: string;
}

/**
 * Answer to one `confirm` frame. `canvasId` is optional so a bare client can
 * still answer, but the web sends it: the daemon refuses an answer whose canvas
 * does not match the suspended request.
 */
export interface AiConfirmRequest {
  requestId: string;
  approved: boolean;
  canvasId?: string;
}

/**
 * The browser's answer to a `renderRequest` frame: one PNG data URL for one
 * request id. The daemon accepts exactly one result per request, and only
 * while that request is still pending.
 */
export interface AiRenderResultRequest {
  requestId: string;
  imageUrl: string;
}

/**
 * The browser's answer to an `exportRequest` frame: the file it just downloaded
 * and its size, or the reason it could not export. The PNG itself never travels
 * back — the browser already saved it, and the tool result must not carry bytes.
 */
export interface AiExportResultRequest {
  requestId: string;
  /** Download filename; present only when the export succeeded. */
  filename?: string;
  /** Size of the downloaded PNG in bytes; present only on success. */
  bytes?: number;
  /** Why the browser could not export; the tool answers export_unavailable. */
  error?: string;
}

/**
 * A rectangle in canvas coordinates: the same units as `CanvasDocument.width`
 * and `height`, origin at the top-left corner.
 */
export interface CanvasRegion {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * `canvas_select`'s UI signal: point the user at one layer or one area. It is a
 * one-way notification (the browser answers nothing), and it never touches the
 * document, so it carries no revision and no undo/redo meaning.
 */
export interface CanvasSelectFrame {
  canvasId: string;
  layerId?: string;
  region?: CanvasRegion;
  /** True when `region` was clipped into the canvas bounds; the region is clipped. */
  clamped?: boolean;
}

/**
 * One frame of the `POST /paint/ai/chat` SSE stream. Frames are partial: each
 * frame carries exactly one of the optional members.
 */
export interface StreamPayload {
  delta?: unknown;
  done?: unknown;
  error?: { code?: unknown; message?: unknown };
  /**
   * One dynamic-tool call from the running turn. Emitted at `item/started`
   * (`running`) and `item/completed` (`ok` / `failed`); `code` names the failure
   * so the UI can localize it without parsing prose.
   */
  tool?: {
    id: string;
    name: string;
    status: 'running' | 'ok' | 'failed';
    code?: string;
  };
  /**
   * A tool waits for the user before it may proceed (delete, export). The turn
   * is suspended until `POST /paint/ai/confirm` answers `id`, or the deadline
   * passes.
   */
  confirm?: {
    id: string;
    title: string;
    detail: string;
    /** CTA wording for this specific action; the web defaults to 「删除」. */
    approveLabel?: string;
  };
  layerCreated?: { id: string; name: string };
  /**
   * The running tool wants a PNG of the canvas. The browser answers with
   * `POST /paint/ai/render-result` and the same request id.
   */
  renderRequest?: { id: string; canvasId: string };
  /**
   * The running tool asks the browser to download the canvas as a PNG. The
   * browser answers with `POST /paint/ai/export-result` and the same id; the
   * tool result carries only the filename and byte count.
   */
  exportRequest?: { id: string; canvasId: string };
  /**
   * The running tool asks the browser to move the UI focus: make `layerId` the
   * active layer, or circle `region` on the canvas. One-way and ephemeral; the
   * browser does not answer and nothing is persisted.
   */
  select?: CanvasSelectFrame;
  /** A short, non-fatal status line; the turn keeps running after it. */
  notice?: string;
}

export interface ApiErrorBody {
  error: {
    code: string;
    message: string;
  };
}

export const LOG_LEVELS = ['debug', 'info', 'warn', 'error'] as const;

export type LogLevel = (typeof LOG_LEVELS)[number];

export const LOG_CATEGORIES = [
  'codex-runtime',
  'canvas-tool',
  'ai-chat',
  'canvas-action',
  'http',
  'sse',
  'system',
] as const;

export type LogCategory = (typeof LOG_CATEGORIES)[number];

/**
 * 消息方向的端点词表：参与一次「谁发给谁」的可命名组件。
 * 前端画拓扑、后端校验共用同一份。`model` 没有任何直接日志，
 * 只存在于术语与拓扑里；前三个可直接观测，后两个由相邻组件代为标注。
 */
export const LOG_COMPONENTS = [
  'browser',
  'daemon',
  'codex',
  'model',
  'sqlite',
] as const;

export type LogComponent = (typeof LOG_COMPONENTS)[number];

/**
 * One structured observability record. A record either describes a finished
 * span (`durationMs` set) or a point event emitted inside a span.
 */
export interface AgentLog {
  id: number;
  traceId: string | null;
  spanId: string | null;
  parentId: string | null;
  timestamp: number;
  level: LogLevel;
  category: LogCategory;
  message: string;
  payload: unknown;
  durationMs: number | null;
  error: string | null;
  canvasId: string | null;
  revision: number | null;
  actor: Actor | null;
  /**
   * 消息的发出方与接收方。只有「消息型」记录才有方向；内部事件
   * （system 启动、进程错误等）保持 `null`，语义是「内部」而非「未知」。
   * 新增的可空字段：旧客户端读取新记录时忽略它们即可正常工作。
   */
  source: LogComponent | null;
  target: LogComponent | null;
}

export interface AgentLogPage {
  items: AgentLog[];
  total: number;
  limit: number;
  offset: number;
}

export interface AgentTraceNode {
  log: AgentLog;
  children: AgentTraceNode[];
}

export interface AgentTrace {
  traceId: string;
  roots: AgentTraceNode[];
}

export interface MonitorCategoryStats {
  category: LogCategory;
  count: number;
  errorCount: number;
}

export interface MonitorStats {
  windowMs: number;
  totalLogs: number;
  /** Every error-level record in the window, across all categories. */
  errorCount: number;
  /** Failed HTTP request ratio; `null` when the window has no HTTP requests. */
  errorRate: number | null;
  requestCount: number;
  requestsPerSecond: number;
  /** HTTP requests that ended in a server failure (5xx, logged at `error`). */
  httpFailureCount: number;
  /** HTTP requests that ended in a client conflict (4xx, logged at `warn`). */
  httpConflictCount: number;
  /** Mean duration of HTTP requests that recorded a duration. */
  avgDurationMs: number;
  /** Completed AI chats excluding user cancellations (the success denominator). */
  aiChatCount: number;
  /** Completed AI chats at info level; aborted chats do not count as success. */
  aiChatSuccessCount: number;
  /** Chats the user cancelled; kept out of the success rate and shown separately. */
  aiChatAbortedCount: number;
  /** `null` until five non-aborted chats completed, so small samples read as unknown. */
  aiChatSuccessRate: number | null;
  categoryCounts: MonitorCategoryStats[];
}
